 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find the prominent L-shaped guide: a connected color component made of
    # perpendicular straight arms, with at least four cells per arm.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        q.append(p)
            comps.append((color, cells))
    guides = []
    for color, cells in comps:
        ys = [p[0] for p in cells]; xs = [p[1] for p in cells]
        hh, ww = max(ys)-min(ys)+1, max(xs)-min(xs)+1
        if len(cells) >= 7 and hh >= 4 and ww >= 4 and len(cells) <= hh + ww:
            guides.append((len(cells), color))
    if not guides:
        return out
    _, paint = max(guides)
    # Recolor the isolated 3-cell L triomino, the small copy of the guide's corner.
    for color, cells in comps:
        if color == paint or len(cells) != 3:
            continue
        ys = [p[0] for p in cells]; xs = [p[1] for p in cells]
        if max(ys)-min(ys) == 1 and max(xs)-min(xs) == 1:
            for y, x in cells:
                out[y][x] = paint
            break
    return out
